function movementRequest(input,expected,closeOld=false){const by=actor(),s=sources();if(expected!==signature(s))throw Error('Estoque alterado; atualize e confira novamente');const id=P.newId(),next=D.plan(s.p.data,s.d.data,s.m.data,input,by,{id,operations:s.o.data}),p=s.p.data.find(p=>p.id===input.produtoId);request={kind:'movement',input,id,expected,closeOld};review(input.tipo.toUpperCase()+' · '+p.nome+'\n'+num(input.quantidade)+' '+p.unCompra+'\n'+placeName(next.entry.origem,s)+' → '+placeName(next.entry.destino,s)+'\nTotal global: '+num(p.estoqueCompra)+' → '+num(next.products.find(p=>p.id===input.produtoId).estoqueCompra)+' '+p.unCompra+'\nNão gera gasto no Financeiro, consumo ou texto no RDO.');}
